export const MISSILE_SOUND_TABLE_113C = MISSILE_SOUNDS_113C

export const MISSILE_SOUND_MAP_113C: Readonly<Record<number, MissileSoundRow113c>> = (() => {
  const map: Record<number, MissileSoundRow113c> = {}
  for (const row of MISSILE_SOUNDS_113C) {
    map[row.id] = row
  }
  return map
})()

export const MISSILE_SOUNDS_BY_NAME_113C: Readonly<Record<string, MissileSoundRow113c>> = (() => {
  const map: Record<string, MissileSoundRow113c> = {}
  for (const row of MISSILE_SOUNDS_113C) {
    if (row.missile) {
      map[row.missile.toLowerCase()] = row
    }
  }
  return map
})()

export function getMissileSoundEntry113c(missileIdOrName: number | string): MissileSoundRow113c | undefined {
  if (typeof missileIdOrName === 'number') {
    if (!Number.isFinite(missileIdOrName) || missileIdOrName < 0) return undefined
    return MISSILE_SOUND_MAP_113C[Math.trunc(missileIdOrName)]
  }
  if (typeof missileIdOrName === 'string') {
    const key = missileIdOrName.trim().toLowerCase()
    return MISSILE_SOUNDS_BY_NAME_113C[key]
  }
  return undefined
}
export const getMissileSounds113c = getMissileSoundEntry113c

